import{_ as s,o as i,c as t,a2 as l}from"./chunks/framework.CdvW4CUT.js";const k=JSON.parse('{"title":"交付与验收","description":"","frontmatter":{"title":"交付与验收"},"headers":[],"relativePath":"guide/delivery.md","filePath":"guide/delivery.md","lastUpdated":null}'),e={name:"guide/delivery.md"};function d(n,a,r,h,o,p){return i(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="交付与验收" tabindex="-1">交付与验收 <a class="header-anchor" href="#交付与验收" aria-label="Permalink to &quot;交付与验收&quot;">​</a></h1><p><span class="level level-optional">⚪ 第 8 节</span></p><p>开发侧交付代码，测试侧按清单验收，两端都只以本规范的数值为准。</p><h2 id="_8-1-开发侧" tabindex="-1">8.1 开发侧 <a class="header-anchor" href="#_8-1-开发侧" aria-label="Permalink to &quot;8.1 开发侧&quot;">​</a></h2><ul class="rules"><li class="must">所有样式引用 Token（CSS 变量），禁止硬编码颜色、字号、间距、圆角、阴影。</li><li class="must">Token 只在全局定义一次，组件内不重新赋值覆盖语义色。</li><li class="must">组件交付时包含全部状态样式（见<a href="/components/button">按钮</a>的状态表）。</li><li class="recommend">Token 文件单独维护（如 <code>tokens.css</code>），按「色彩 / 字体 / 间距 / 圆角阴影」分组并加注释。</li><li class="recommend">新增 Token 前先确认已有 Token 无法覆盖，避免同义 Token 膨胀。</li></ul><h3 id="自查命令" tabindex="-1">自查命令 <a class="header-anchor" href="#自查命令" aria-label="Permalink to &quot;自查命令&quot;">​</a></h3><p>提交前用正则扫一遍硬编码，命中即需修正：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 硬编码颜色</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#6F42C1;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> -rnE</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> &quot;#[0-9a-fA-F]{3,8}\\b|rgba?\\(&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> src</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;">&quot;*.vue&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;">&quot;*.css&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#D73A49;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#6F42C1;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> &quot;tokens.css&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 非法字号</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#6F42C1;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> -rnE</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> &quot;font-size:\\s*(13|15|17|18)px&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> src</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 非法间距</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#6F42C1;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> -rnE</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> &quot;(margin|padding)[^:]*:\\s*(5|6|7|9|10|11|13|14|15|18|25|30)px&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> src</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="_8-2-测试侧走查清单" tabindex="-1">8.2 测试侧走查清单 <a class="header-anchor" href="#_8-2-测试侧走查清单" aria-label="Permalink to &quot;8.2 测试侧走查清单&quot;">​</a></h2><p>逐项打勾，任一 <span class="level level-must">强制</span> 项不通过，验收即为不通过。</p><h3 id="色彩" tabindex="-1">色彩 <a class="header-anchor" href="#色彩" aria-label="Permalink to &quot;色彩&quot;">​</a></h3><ul class="checklist"><li>页面中不存在规范外的色值（可用取色器抽查 5 个元素）</li><li>主按钮、链接、选中态均为 <code>--color-primary</code> 系列</li><li>错误、成功、警告三类提示分别使用对应语义色</li><li>禁用态文字为 <code>--color-text-disabled</code>，且可辨识为「不可用」</li></ul><h3 id="排版" tabindex="-1">排版 <a class="header-anchor" href="#排版" aria-label="Permalink to &quot;排版&quot;">​</a></h3><ul class="checklist"><li>页面内字号只出现 20 / 16 / 14 / 12 四档</li><li>字重只出现 400 与 600</li><li>多行文本行高一致，无挤压或过疏</li></ul><h3 id="间距与布局" tabindex="-1">间距与布局 <a class="header-anchor" href="#间距与布局" aria-label="Permalink to &quot;间距与布局&quot;">​</a></h3><ul class="checklist"><li>所有间距为 4 的倍数，且落在允许值内</li><li>左侧菜单 200px（折叠 64px）、顶部导航 90px</li><li>内容区左右留白 24px，各页面一致</li><li>同一容器上下内边距相等</li></ul><h3 id="圆角与阴影" tabindex="-1">圆角与阴影 <a class="header-anchor" href="#圆角与阴影" aria-label="Permalink to &quot;圆角与阴影&quot;">​</a></h3><ul class="checklist"><li>圆角只有 2 / 4 / 8px 三档</li><li>阴影只用于浮层，平面内容无阴影</li><li>弹窗用 <code>--shadow-modal</code>，卡片用 <code>--shadow-card</code></li></ul><h3 id="组件状态" tabindex="-1">组件状态 <a class="header-anchor" href="#组件状态" aria-label="Permalink to &quot;组件状态&quot;">​</a></h3><ul class="checklist"><li>按钮 5 个状态全部实现（default / hover / active / disabled / loading）</li><li>同一区域只有一个主按钮</li><li>表单标签顶部对齐，必填星号在 Label 前</li><li>错误提示在输入框下方且为红色</li><li>表格操作列为右侧文字按钮</li><li>空数据有完整空状态</li><li>弹窗按钮「取消在左、确认在右」</li><li>弹窗遮罩为 <code>rgba(0,0,0,0.4)</code></li></ul><h3 id="交互与可访问性" tabindex="-1">交互与可访问性 <a class="header-anchor" href="#交互与可访问性" aria-label="Permalink to &quot;交互与可访问性&quot;">​</a></h3><ul class="checklist"><li>可点击区域不小于 32px</li><li>正文对比度 ≥ 4.5:1，大字号 / 图标 ≥ 3:1</li><li>动效时长 200ms，无布局属性过渡</li><li>键盘可完成全部操作，焦点可见</li><li>状态不单靠颜色传达</li></ul><h2 id="_8-3-常见缺陷对照" tabindex="-1">8.3 常见缺陷对照 <a class="header-anchor" href="#_8-3-常见缺陷对照" aria-label="Permalink to &quot;8.3 常见缺陷对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缺陷</th><th>违反条款</th><th>修正方式</th></tr></thead><tbody><tr><td>按钮只做 hover，无 active</td><td>6.1 状态</td><td>补 <code>--color-primary-active</code></td></tr><tr><td>loading 期间仍可点击</td><td>6.1 状态</td><td>加 <code>disabled</code> 并拦截提交</td></tr><tr><td>表单标签左对齐</td><td>6.2 表单</td><td>改为顶部对齐，间距 8px</td></tr><tr><td>必填星号在 Label 之后</td><td>6.2 表单</td><td>移到 Label 前</td></tr><tr><td>表格操作用彩色图标按钮</td><td>6.3 表格</td><td>改为文字按钮</td></tr><tr><td>查询无结果时留白</td><td>6.3 表格</td><td>补空状态三件套</td></tr><tr><td>弹窗确认在左、取消在右</td><td>6.4 弹窗</td><td>调换顺序</td></tr><tr><td>背景色写 <code>#f5f5f5</code></td><td>2 色彩</td><td>改用 <code>--color-bg-page</code></td></tr><tr><td>间距 10px / 15px</td><td>4 间距</td><td>就近取允许值</td></tr><tr><td>弹窗遮罩 <code>rgba(0,0,0,0.6)</code></td><td>6.4 弹窗</td><td>统一 <code>0.4</code></td></tr></tbody></table><h2 id="_8-4-版本与变更" tabindex="-1">8.4 版本与变更 <a class="header-anchor" href="#_8-4-版本与变更" aria-label="Permalink to &quot;8.4 版本与变更&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>处理</th></tr></thead><tbody><tr><td>修改数值</td><td>同步更新源文件、本站、Trae 规则三处，升次版本号</td></tr><tr><td>新增规则或 Token</td><td>标注强制等级与用途，升主版本号</td></tr><tr><td>废弃规则</td><td>保留条目并标注「已废弃 · 替代项」，不直接删除</td></tr></tbody></table>`,26)])])}const u=s(e,[["render",d]]);export{k as __pageData,u as default};
